"Abstand Anfang / Ende macht aus der Lasche eine Teillasche. Weitere geschlossene Profile in der Skizze werden zu Ausschnitten in der Platte. Bohrungen und Fenster in einer Lasche: Mitte entlang der Kante (bei einer gebogenen Kante entlang des Bogens), Mitte ab Ende der Biegung, Größe – sie erscheinen auch in der Abwicklung. Geht eine gebogene Kante ohne Knick in ihre Nachbarkante über und haben beide eine Lasche mit gleichem Biegewinkel, laufen die Laschen ohne Freischnitt ineinander über. „Kontur aus Skizze“ schneidet die geschlossenen Profile einer Skizze aus der Lasche: ihr X läuft entlang der Kante, ihr Y in die Lasche hinein, der Nullpunkt liegt am Kantenanfang auf dem Ende der Biegung (verschiebbar).":"Een afstand begin / einde maakt van de flens een deelflens. Overige gesloten profielen in de schets worden uitsparingen in de plaat. Gaten en vensters in een flens: midden langs de rand (bij een gebogen rand langs de boog), midden vanaf het einde van de buiging, grootte – ze verschijnen ook in de uitslag. Gaat een gebogen rand zonder knik over in de naburige rand en hebben beide een flens met dezelfde buighoek, dan lopen de flenzen zonder vrijsnede in elkaar over. „Contour uit schets“ snijdt de gesloten profielen van een schets uit de flens: de X loopt langs de rand, de Y de flens in, het nulpunt ligt aan het begin van de rand op het einde van de buiging (verschuifbaar).",
