"Alle Einstellungen, Symbolleisten-Anpassungen und eigenen Tastenkürzel auf die Vorgaben zurücksetzen?\n\nEigene Werkzeugbibliotheken, Materialien und Vorlagen bleiben erhalten.":"Alle voorkeuren, werkbalkaanpassingen en eigen sneltoetsen terugzetten naar de standaardwaarden?\n\nEigen gereedschapsbibliotheken, materialen en sjablonen blijven behouden.",
"Alle Flächen des Merkmals wählen: bei einer Bohrung die Wand (und Senkung, Boden), bei einer Tasche Wände und Boden, bei einem Zapfen Mantel und Stirnfläche. Das Merkmal wandert um X/Y/Z; die alte Stelle wird geschlossen. Geht auch bei importierten STEP-Teilen ohne Verlauf. Beim ersten Mal lädt der große Geometriekern (einige Sekunden).":"Selecteer alle vlakken van de feature: bij een gat de wand (en verzinking, bodem), bij een kamer de wanden en bodem, bij een nok de mantel en het kopvlak. De feature verschuift over X/Y/Z; de oude plek wordt gesloten. Werkt ook bij geïmporteerde STEP-onderdelen zonder historie. De eerste keer wordt de grote geometriekernel geladen (enkele seconden).",
"Alle Flächen wählen, die verschwinden sollen (bei einer Tasche Wände und Boden, bei einer Bohrung die Wand, bei einer Verrundung die Rundung). Die Nachbarflächen werden über die Lücke verlängert. Der Schritt rechnet bei Änderungen am Körper mit; beim ersten Mal lädt dafür der große Geometriekern (einige Sekunden).":"Kies alle vlakken die moeten verdwijnen (bij een kamer wanden en bodem, bij een gat de wand, bij een afronding het afgeronde vlak). De naburige vlakken worden over de opening verlengd. De stap rekent mee bij wijzigingen aan het lichaam; de eerste keer wordt hiervoor de volledige geometriekernel geladen (enkele seconden).",
