"Dieser Browser unterstützt keine SpaceMouse (WebHID). Bitte Chrome, Edge oder die Desktop-App verwenden.":"Deze browser ondersteunt geen SpaceMouse (WebHID). Gebruik Chrome, Edge of de desktop-app.",
