"Drehen: Das Teil muss rotationssymmetrisch um die Z-Achse liegen. Z0 = Planfläche oben, X = Durchmesser.":"Draaien: het onderdeel moet rotatiesymmetrisch om de Z-as liggen. Z0 = vlakke kant boven, X = diameter.",
"Drehen: Drehpunkt anklicken, dann den Winkel mit der Maus zeigen (Vorschau). Esc beendet.":"Draaien: klik op het draaipunt en geef daarna de hoek aan met de muis (voorvertoning). Esc beëindigt.",
"Drehen: Durchmesser, auf dem der Revolver schaltet (Okuma, LinuxCNC). 0 = Rohteil-Ø + 200 mm":"Draaien: diameter waarop de revolver schakelt (Okuma, LinuxCNC). 0 = Ø ruw materiaal + 200 mm",
"Drehen: Elemente wählen, dann Drehpunkt anklicken und den Winkel mit der Maus zeigen (Vorschau); auch als Kopie":"Roteren: kies elementen, klik op het draaipunt en geef de hoek met de muis aan (voorbeeld); ook als kopie",
