"Drehen: Z vor der Planfläche, auf dem der Revolver schaltet. 0 = Sicherheitsabstand + 100 mm":"Draaien: Z voor het vlakke einde waarop de revolver schakelt. 0 = veiligheidsafstand + 100 mm",
