"Drehgeschwindigkeit":"Draaisnelheid",
"Drehmaschine mit Y-Achse: Schlüsselflächen, Konturen und Taschen auf der Planfläche fahren mit feststehendem Teil (C fest) in X und Y – genauer als die Polar-Interpolation. Was über den Y-Weg hinausgeht, bleibt bei der Polar-Interpolation.":"Draaibank met Y-as: sleutelvlakken, contouren en kamers op het voorvlak worden bij stilstaand werkstuk (C vast) in X en Y gevolgd – nauwkeuriger dan poolinterpolatie. Wat buiten de Y-slag valt, blijft met poolinterpolatie.",
