"Durchzug {0}: Vorbohrung Ø {1} mm wird auf Ø {2} mm aufgeweitet (Faktor {3}).":"Doortrek {0}: voorboring Ø {1} mm wordt opgerekt tot Ø {2} mm (factor {3}).",
"Durchzug {0}: liegt {1} mm neben dem Rand (weniger als 2 × Blechdicke) – der Rand beult aus.":"Doortrek {0}: ligt {1} mm naast de rand (minder dan 2 × plaatdikte) – de rand bolt uit.",
"Durchzug {0}: zu hoch für diese Bohrung (die Vorbohrung bliebe ohne Durchmesser)":"Doortrek {0}: te hoog voor dit gat (de voorboring zou geen diameter overhouden)",
"Durchzug: der Rand einer runden Bohrung wird zu einem Kragen hochgezogen, etwa als Gewindedurchzug. Der Bohrungsdurchmesser der Skizze ist der fertige Innendurchmesser; im Zuschnitt wird die kleinere Vorbohrung geschnitten.":"Doortrek: de rand van een rond gat wordt omhooggetrokken tot een kraag, bijvoorbeeld als schroefdraaddoortrek. De gatdiameter van de schets is de afgewerkte binnendiameter; in de uitslag wordt de kleinere voorboring gesneden.",
