"Ein Fusion-Design mit seiner Zeitachse übernehmen: über das Export-Skript für Fusion":"Een Fusion-ontwerp met zijn tijdlijn overnemen: via het exportscript voor Fusion",
"Ein Gelenk anlegen: ZUSAMMENBAU → „Gelenk“ (J), erst das bewegliche Teil, dann das feste anklicken, Art „Drehgelenk“ oder „Schiebegelenk“.":"Een scharnier maken: SAMENSTELLEN → „Scharnier” (J), klik eerst op het beweegbare onderdeel, dan op het vaste, type „Draaigewricht” of „Schuifgewricht”.",
"Ein Rechteck zeichnen: Werkzeug „Rechteck“ (R), zwei Ecken anklicken. Maße kann man direkt eintippen, z. B. 80 und 50.":"Een rechthoek tekenen: gereedschap „Rechthoek” (R), klik op twee hoeken. Maten kunt u direct intypen, bijv. 80 en 50.",
"Ein Rechtsklick in einen Dialog (nicht in ein Eingabefeld) drückt dessen OK-Schaltfläche":"Een rechtsklik in een dialoogvenster (niet in een invoerveld) drukt op de OK-knop",
"Ein anderes gespeichertes Design als Komponente einfügen":"Een ander opgeslagen ontwerp als component invoegen",
"Ein eingefügter Satz verschiebt alle folgenden Satznummern – so zählen sie nicht als Änderung":"Een ingevoegde regel verschuift alle volgende regelnummers – zo tellen ze niet als wijziging",
"Ein fertiges Teil mit Konstruktion und Fräsbearbeitung":"Een klaar onderdeel met constructie en freesbewerking",
"Ein gerollter Rand über 350° schließt sich zum Rohr – das ist so nicht herstellbar":"Een omgerolde rand van meer dan 350° sluit zich tot een buis – zo is dat niet te maken",
"Ein geschlossenes Netz in einen Volumenkörper umwandeln (jedes Dreieck wird eine Fläche)":"Een gesloten mesh omzetten in een volumelichaam (elke driehoek wordt een vlak)",
"Ein leeres Design beginnen":"Een leeg ontwerp beginnen",
"Ein runder Fräser lässt in jeder Innenecke seinen Radius stehen – ein eckiges Gegenstück passt dann nicht hinein. Der Freistich fährt an jeder scharfen Innenecke kurz in die Ecke und zurück.{0}{1}":"Een ronde frees laat in elke binnenhoek zijn radius staan – een hoekig tegenstuk past er dan niet in. De vrijsteek gaat bij elke scherpe binnenhoek kort de hoek in en terug.{0}{1}",
"Ein verbundener Agent arbeitet am geöffneten Entwurf: Er liest und ändert die Zeitachse, fragt Körper, Volumen und Fehler ab, holt Normteile aus dem Bauteilkatalog, lässt sich ein Bild der Ansicht geben, exportiert STEP oder STL, legt Werkzeuge und Fertigungsoperationen an und gibt das NC-Programm aus – das vor dem ersten Schnitt zu prüfen bleibt. Auf Dateien, Einstellungen und andere Entwürfe hat er keinen Zugriff. Jede Änderung ist ein Schritt, den Strg+Z zurücknimmt.":"Een verbonden agent werkt aan het geopende ontwerp: hij leest en wijzigt de tijdlijn, vraagt lichamen, volumes en fouten op, haalt normonderdelen uit de onderdelencatalogus, laat zich een beeld van de weergave geven, exporteert STEP of STL, maakt gereedschappen en fabricagebewerkingen aan en geeft het NC-programma uit – dat vóór de eerste snede nog gecontroleerd moet worden. Hij heeft geen toegang tot bestanden, voorkeuren en andere ontwerpen. Elke wijziging is een stap die Ctrl+Z ongedaan maakt.",
"Ein zweiter Klick auf die Schaltfläche des Zeichenwerkzeugs schaltet zurück auf Auswählen":"Een tweede klik op de knop van het tekengereedschap schakelt terug naar Selecteren",
"Ein-/Ausblenden":"Tonen/Verbergen",
"Ein-/Ausfahrten und Übergänge":"Aanloop, uitloop en overgangen",
"Einblenden":"Tonen",
"Einblendungen":"Overlays",
"Eine .f3d-Datei ist ein geschlossenes Format – die Zeitachse darin kann kein anderes Programm lesen. Fusion selbst gibt sie aber über seine Skript-Schnittstelle heraus:":"Een .f3d-bestand is een gesloten formaat – de tijdlijn erin kan geen ander programma lezen. Fusion zelf geeft deze echter vrij via zijn scriptinterface:",
"Eine .ofab-Datei von diesem Computer öffnen":"Een .ofab-bestand van deze computer openen",
"Eine Bahn entlang jeder Innenecke/Hohlkehle, in der das Werkzeug zwei Flächen zugleich berührt – zum Ausräumen nach dem Schlichten.":"Eén baan langs elke binnenhoek/holle afronding waar het gereedschap twee vlakken tegelijk raakt – om na het nafrezen op te ruimen.",
"Eine Bearbeitung anlegen, z. B. FRÄSEN → „2D-Kontur“ oder „Planfräsen“, Werkzeug wählen, OK.":"Een bewerking maken, bijv. FREZEN → „2D-contour” of „Vlakfrezen”, gereedschap kiezen, OK.",
"Eine Bohrung setzen: „Bohrung“ (H), auf die Oberseite klicken, Durchmesser wählen, OK. (Eine Extrusion mit „Ausschneiden“ zählt auch.)":"Een gat plaatsen: „Gat” (H), klik op de bovenkant, kies een diameter, OK. (Een extrusie met „Uitsnijden” telt ook.)",
"Eine Explosionsansicht braucht mindestens zwei Körper.":"Een exploded view heeft minstens twee lichamen nodig.",
"Eine Explosionsansicht öffnen: „Explosionsansicht“ – „Montageanleitung“ macht daraus eine Seite mit Bildern.":"Een exploded view openen: „Exploded view” – „Montagehandleiding” maakt er een pagina met afbeeldingen van.",
"Eine Fläche, Bohrung oder einen Zapfen anklicken.":"Klik op een vlak, gat of pen.",
"Eine Fläche, Bohrung oder einen Zapfen eines Körpers anklicken.":"Klik op een vlak, gat of pen van een lichaam.",
"Eine Konfiguration merkt sich die Ausdrücke aller Parameter unter einem Namen – etwa „kurz“ und „lang“. Ein Klick stellt die Variante wieder her.":"Een configuratie onthoudt de uitdrukkingen van alle parameters onder een naam – bijvoorbeeld „kort” en „lang”. Met één klik is de variant terug.",
"Eine Platte mit Bohrung und abgerundeten Kanten – Skizze, Extrusion, Bohrung und Verrundung.":"Een plaat met een gat en afgeronde randen – schets, extrusie, gat en afronding.",
"Eine STEP-, IGES-, STL-, OBJ-, 3MF- oder PLY-Datei in ein neues Design einfügen":"Een STEP-, IGES-, STL-, OBJ-, 3MF- of PLY-bestand in een nieuw ontwerp invoegen",
"Eine Seite":"Eén zijde",
"Eine Seite mit einem Bild je Montageschritt (Explosion rückwärts), druckbar und als PDF":"Een pagina met één afbeelding per montagestap (explosie omgekeerd), afdrukbaar en als PDF",
"Eine Variante speichern: VERWALTEN → „Konfigurieren“, Name z. B. dünn.":"Een variant opslaan: BEHEREN → „Configureren”, naam bijv. dun.",
"Eine der gewählten Kanten oder Flächen wurde nicht mehr gefunden – neu wählen.":"Een van de gekozen randen of vlakken is niet meer gevonden – opnieuw kiezen.",
"Einen Bewegungsablauf anlegen: „Bewegungsablauf“, „+ Schritt“, dann ▶ – „Prüfen“ meldet Zusammenstöße mit Zeitpunkt.":"Een bewegingsstudie maken: „Bewegingsstudie”, „+ Stap”, dan ▶ – „Controleren” meldt botsingen met tijdstip.",
