"Erzeugt eine neue Fläche im Abstand zu den gewählten Flächen (negativ = nach innen). Der Körper bleibt unverändert.":"Maakt een nieuw oppervlak op afstand van de gekozen vlakken (negatief = naar binnen). Het lichaam blijft ongewijzigd.",
"Erzeugt einen Tastzyklus (Heidenhain TCH PROBE 417/412/413/411/410, Fanuc Renishaw G65 P98xx).":"Maakt een tastcyclus (Heidenhain TCH PROBE 417/412/413/411/410, Fanuc Renishaw G65 P98xx).",
