"Es braucht einen Körper – falls noch keiner da ist, zuerst die Aufgabe „Erstes Teil“ machen.":"Er is een lichaam nodig – als er nog geen is, eerst de les „Eerste onderdeel” doen.",
"Es braucht mindestens zwei Körper (z. B. zwei Extrusionen mit „Neuer Körper“).":"Er zijn minstens twee lichamen nodig (bijv. twee extrusies met „Nieuw lichaam”).",
