"Fläche an ihren Rändern tangential weiterführen":"Vlak aan de randen tangentieel verlengen",
"Fläche anklicken – die Bohrung entsteht mit":"Klik een vlak aan – het gat wordt meteen gemaakt",
"Fläche anklicken: an jedem Klickpunkt entsteht die Durchgangsbohrung für die Schraube (ISO 273, Reihe mittel) durch alle Teile, die dort aufeinanderliegen – für Senkschrauben mit 90°-Senkung, für Zylinderschrauben auf Wunsch mit Senkbohrung (DIN 974-1, Reihe 1) so tief wie der Kopf. Die Schraube sitzt gleich darin. Bohrung und Schraube lassen sich danach im Verlauf ändern.":"Klik een vlak aan: op elk aangeklikt punt ontstaat het doorgaande gat voor de schroef (ISO 273, reeks middel) door alle delen die daar op elkaar liggen – voor verzonken schroeven met 90°-verzinking, voor cilinderkopschroeven op verzoek met een verdiept kopgat (DIN 974-1, reeks 1) zo diep als de kop. De schroef zit meteen in het gat. Gat en schroef kunnen daarna in de tijdlijn worden gewijzigd.",
"Fläche eines Körpers anklicken: ihr Rand kommt als Kontur in die Skizze. Eine Kante anklicken projiziert nur diese Kante (Kreise bleiben Kreise). Projizierte Geometrie ist violett.":"Klik op een vlak van een lichaam: de rand ervan komt als contour in de schets. Klikken op een rand projecteert alleen die rand (cirkels blijven cirkels). Geprojecteerde geometrie is paars.",
"Fläche ersetzen":"Vlak vervangen",
"Fläche ersetzen: eine ebene Fläche auf eine andere Ebene legen – der Körper wächst oder wird gekürzt":"Vlak vervangen: een vlak vlak op een ander vlak leggen – het lichaam groeit of wordt korter",
"Fläche extrudieren":"Vlak extruderen",
"Fläche gewählt – Skizze, Drücken/Ziehen (Q), Extrusion (E), Bohrung (H) oder Schale nimmt sie. Umschalt/Strg + Klick: weitere Flächen.":"Vlak geselecteerd – Schets, Duwen/Trekken (Q), Extrusie (E), Gat (H) of Schil gebruikt het. Shift/Ctrl + klik: meer vlakken.",
"Fläche hinter den Fenstern – gilt, wenn oben das Design „Eigenes“ gewählt ist":"Vlak achter de vensters – geldt wanneer hierboven het thema „Eigen“ is gekozen",
"Fläche löschen":"Vlak verwijderen",
"Fläche löschen: Bohrungen, Taschen, Verrundungen oder Fasen entfernen – die Nachbarflächen schließen die Lücke":"Vlak verwijderen: gaten, kamers, afrondingen of afschuiningen verwijderen – de naburige vlakken sluiten de opening",
"Fläche löschen: OK schließt die Lücke. Den ganzen Körper entfernt Entf, wenn er im Browser gewählt ist.":"Vlak verwijderen: OK sluit de opening. Het hele lichaam verwijdert Del, als het in de browser is geselecteerd.",
"Fläche mit Loch":"Vlak met gat",
