"Fläche versetzen":"Vlak verschuiven",
"Fläche versetzen: ebene Flächen verschieben, Bohrungen und Zapfen im Durchmesser ändern":"Vlak verschuiven: vlakke vlakken verplaatsen, diameter van gaten en tappen wijzigen",
