"Flächen am Teilende (Zweiflach, Vierkant, Sechskant) mit einem angetriebenen Schaftfräser entlang Z. Schlüsselweite = doppelter Abstand der Fläche von der Drehachse. X und C fahren gemeinsam (Polar-Interpolation, Fanuc G12.1); ohne diese Vorlage im Postprozessor werden kurze X/C-Schritte ausgegeben.":"Vlakken aan het uiteinde van het onderdeel (tweevlak, vierkant, zeskant) met een aangedreven vingerfrees langs Z. Sleutelwijdte = tweemaal de afstand van het vlak tot de draaias. X en C bewegen samen (poolinterpolatie, Fanuc G12.1); zonder dit sjabloon in de postprocessor worden korte X/C-stapjes uitgevoerd.",
"Flächen an einer Ebene oder Skizze auftrennen":"Vlakken bij een vlak of schets splitsen",
"Flächen an ihren Rändern verbinden – ein geschlossener Verbund wird ein Volumenkörper":"Vlakken aan hun randen verbinden – een gesloten geheel wordt een volumelichaam",
"Flächen anklicken, die aufgedickt werden (erneut klicken entfernt).":"Klik op vlakken die worden verdikt (nogmaals klikken verwijdert).",
"Flächen anklicken, die geneigt werden (erneut klicken entfernt).":"Klik op de vlakken die schuin moeten komen (opnieuw klikken verwijdert).",
"Flächen anklicken, die offen sein sollen.":"Klik op de vlakken die open moeten zijn.",
"Flächen anklicken, die versetzt werden (erneut klicken entfernt).":"Klik op vlakken die worden verschoven (nogmaals klikken verwijdert).",
"Flächen eine Wandstärke geben":"Vlakken een wanddikte geven",
"Flächen im Modell":"Vlakken in model",
"Flächen mit gemeinsamen Kanten werden zu einer verbunden. Ist die Hülle rundum geschlossen, entsteht ein Volumenkörper (danach normal weiterbearbeitbar). Lücken größer als die Toleranz bleiben offen.":"Oppervlakken met gemeenschappelijke randen worden tot één verbonden. Als de schil rondom gesloten is, ontstaat een volumelichaam (daarna normaal verder te bewerken). Openingen groter dan de tolerantie blijven open.",
