"Für eine Bohrung Ø {0} mm gibt es in dieser Reihe keine passende Schraube.":"Voor een gat Ø {0} mm is er in deze reeks geen passende schroef.",
"Für schräge Richtungen eine Konstruktionsachse anlegen (durch zwei Punkte, einen Zylinder oder zwei Ebenen) – sie erscheint dann hier als Richtung.":"Maak voor schuine richtingen een constructieas aan (door twee punten, een cilinder of twee vlakken) – deze verschijnt dan hier als richting.",
"Für wirbelndes Fräsen entlang einer Linie die Nutbreite angeben":"Geef voor trochoïdaal frezen langs een lijn de sleufbreedte op",
