"Gelenkursprung: Bohrung, Zapfen oder Fläche anklicken (mehrere nacheinander möglich).":"Scharnieroorsprong: klik op een gat, pen of vlak (meerdere achter elkaar mogelijk).",
"Gelenkursprünge ({0})":"Scharnieroorsprongen ({0})",
"Gelenkursprünge neu wählen":"Scharnieroorsprongen opnieuw kiezen",
"Gemeinsame Schnittkanten nur einmal schneiden":"Gemeenschappelijke snijkanten slechts één keer snijden",
"Gemeinsame Schnittkanten: liegen zwei Zuschnitte genau eine Schnittfuge auseinander (beim Schachteln als Abstand die Schnittfuge eintragen), fällt ihre Bahn auf der gemeinsamen Kante zusammen und wird nur einmal geschnitten. Der Anschnitt liegt nie in einem Nachbarteil: ist neben einer Kontur kein freier Abfall, wird auf der Kontur eingestochen. Nach „Vorschau“ zeigt ein Bild je Tafel die Bahn, bevor die Dateien gespeichert werden.":"Gemeenschappelijke snijkanten: liggen twee uitgesneden delen precies één snijbreedte uit elkaar (voer bij het nesten de snijbreedte als afstand in), dan valt hun baan op de gemeenschappelijke kant samen en wordt die maar één keer gesneden. De inloop ligt nooit in een naastgelegen deel: is er naast een contour geen vrij afval, dan wordt op de contour doorgeboord. Na “Voorbeeld” toont een afbeelding per plaat de baan voordat de bestanden worden opgeslagen.",
