"Gerade Linien der Skizze, die zu keinem Profil gehören (auch Hilfslinien). Biegung: die Linie ist die Mitte der Biegezone, die Skizze dort der Zuschnitt – das größte Stück der Platte bleibt liegen, alles jenseits der Linie schwenkt mit seinen Laschen mit. Die Linie gilt über die ganze Platte. Sicke: eine Rippe entlang der Linie, im Querschnitt und an den Enden rund; das Blech behält seine Dicke.":"Rechte lijnen van de schets die bij geen enkel profiel horen (ook hulplijnen). Buiging: de lijn is het midden van de buigzone, de schets is daar de uitslag – het grootste stuk van de plaat blijft liggen, alles voorbij de lijn zwenkt met zijn flenzen mee. De lijn geldt over de hele plaat. Sik: een rib langs de lijn, rond in doorsnede en aan de uiteinden; de plaat behoudt zijn dikte.",
"Gerade Nuten (Langloch oder Linie mit Nutbreite) gehen als Nutzyklus der Steuerung heraus.":"Rechte gleuven (sleufgat of lijn met gleufbreedte) worden uitgevoerd als gleufcyclus van de besturing.",
