"Geschafft! Das Teil steht in der Zeitleiste unten – ein Doppelklick auf einen Schritt ändert ihn nachträglich. Weiter geht es mit „Maße als Parameter“ oder „Vom Teil zum NC-Programm“.":"Gelukt! Het onderdeel staat in de tijdlijn onderaan – dubbelklik op een stap om hem achteraf te wijzigen. Ga verder met „Maten als parameters” of „Van onderdeel naar NC-programma”.",
"Geschlossen":"Gesloten",
"Geschlossen (Gehrung)":"Gesloten (verstek)",
"Geschlossen: Laschen an zwei Nachbarkanten laufen bis zur Winkelhalbierenden der Ecke und lassen dort den Spalt frei. Die Eckfreistellung sitzt, wo sich die Biegezonen kreuzen – in der Abwicklung und im gebogenen Teil. Auch eine Lasche an einer gebogenen Kante wird an einer echten Ecke auf Gehrung geschnitten (dort ohne Eckfreistellung).":"Gesloten: flenzen aan twee naburige randen lopen tot de bissectrice van de hoek en laten daar de spleet vrij. De hoekontlasting zit waar de buigzones elkaar kruisen – in de uitslag en in het gebogen deel. Ook een flens aan een gebogen rand wordt bij een echte hoek op verstek gesneden (daar zonder hoekontlasting).",
"Geschlossene Kette {0}":"Gesloten keten {0}",
"Geschlossene Profile begrenzen den Bereich.":"Gesloten profielen begrenzen het gebied.",
