"Geschlossene Profile werden zu ebenen Flächen – z. B. Deckel und Boden, um Flächen anschließend zu einem Körper zusammenzufügen.":"Gesloten profielen worden vlakke oppervlakken – bijv. deksel en bodem, om oppervlakken daarna tot een lichaam samen te voegen.",
