"Gewindebohrung im untersten Teil":"Draadgat in het onderste deel",
"Gewindebohrung im untersten Teil: die Durchgangsbohrung endet, wo das unterste Teil beginnt; dort entsteht das Kernloch mit Gewinde – drei Gewindegänge tiefer, als die Schraube reicht, oder durch das ganze Teil. Liegt nur ein Teil unter dem Punkt, bekommt es das Gewinde von der Fläche an. „Länge passend zur Einschraubtiefe“ nimmt die nächste Länge der Reihe, mit der die Schraube etwa so tief im Gewinde sitzt, wie ihr Gewinde dick ist (Richtwert für Stahl) – aber nie länger, als das Teil dick ist.":"Tapgat in het onderste deel: het doorgaande gat eindigt waar het onderste deel begint; daar ontstaat het kerngat met schroefdraad – drie schroefdraadgangen dieper dan de schroef reikt, of door het hele deel. Ligt er maar één deel onder het punt, dan krijgt dat de schroefdraad vanaf het vlak. „Lengte passend bij de inschroefdiepte” kiest de eerstvolgende lengte uit de reeks waarbij de schroef ongeveer zo diep in de schroefdraad zit als haar schroefdraad dik is (richtwaarde voor staal) – maar nooit langer dan het deel dik is.",
"Gewindebohrung {0} – Einschraubtiefe nur {1} mm":"draadgat {0} – inschroefdiepte slechts {1} mm",
