"Gleiche Durchmesser ergeben ein Rohr, verschiedene einen Kegelstumpf. Die Abwicklung wird auf der neutralen Faser gerechnet (Innenfläche + K-Faktor × Blechdicke); beim Runden liegt sie näher an der Blechmitte als beim Abkanten – üblich ist ein K-Faktor von 0,45 bis 0,5. Mit einer Blechregel gelten deren Dicke und K-Faktor. Der Nahtspalt bleibt am größeren Durchmesser offen (0 = stumpf gestoßen, im Körper dann ein Schlitz von 0,01 mm).":"Gelijke diameters geven een buis, verschillende een afgeknotte kegel. De uitslag wordt berekend op de neutrale vezel (binnenvlak + K-factor × plaatdikte); bij het walsen ligt deze dichter bij het midden van de plaat dan bij het kanten – gebruikelijk is een K-factor van 0,45 tot 0,5. Met een plaatregel gelden de dikte en de K-factor daarvan. De naadspleet blijft open bij de grotere diameter (0 = stomp gestoten, in het lichaam dan een sleuf van 0,01 mm).",
