"Halbzeug: Nennmaße der Norm, auf jede Länge zugeschnitten. Nicht jede Paarung von Maß und Wanddicke ist bei jedem Händler am Lager. Ein Rohr entlang einer Skizzenlinie – auch um Ecken und Bögen – legt der Befehl „Rohr“ an.":"Halffabricaat: nominale maten van de norm, op elke lengte gezaagd. Niet elke combinatie van maat en wanddikte is bij elke leverancier op voorraad. Een buis langs een schetslijn – ook om hoeken en bogen – maakt u met de opdracht „Buis”.",
