"Heidenhain: an der Steuerung die Datenübertragung über Ethernet freigeben (wie für TNCremo, LSV2, Port 19000); Standardordner TNC 640 TNC:\\nc_prog\\, iTNC 530 TNC:\\. FTP: Port 21, Ordner z. B. /_N_WKS_DIR oder /NC. Netzwerkordner: Pfad wie \\\\MASCHINE\\NC oder Z:\\NC. DNC: Wandler als TCP-Server (raw), meist Port 4001; an der Steuerung „Abarbeiten extern“, DNC oder TAPE starten.":"Heidenhain: schakel op de besturing de gegevensoverdracht via Ethernet in (zoals voor TNCremo, LSV2, poort 19000); standaardmap TNC 640 TNC:\\nc_prog\\, iTNC 530 TNC:\\. FTP: poort 21, map bijv. /_N_WKS_DIR of /NC. Netwerkmap: pad zoals \\\\MASCHINE\\NC of Z:\\NC. DNC: converter als TCP-server (raw), meestal poort 4001; start op de besturing “Extern afwerken”, DNC of TAPE.",
