"Im Programm: die Designs liegen im Speicher des Programms auf diesem Computer. Ordner: jedes Design liegt zusätzlich als .ofab-Datei in einem Ordner Ihrer Wahl, z. B. auf einem Netzlaufwerk oder in einem synchronisierten Ordner. Die gespeicherten Versionen bleiben im Programm.":"In het programma: de ontwerpen staan in het geheugen van het programma op deze computer. Map: elk ontwerp staat bovendien als .ofab-bestand in een map naar keuze, bijvoorbeeld op een netwerkschijf of in een gesynchroniseerde map. De opgeslagen versies blijven in het programma.",
"Im Setup gewählt, bestimmt die Maschine Postprozessor, Eilgang (Laufzeit) und die Grenzwert-Prüfungen.":"Indien gekozen in de opspanning, bepaalt de machine de postprocessor, ijlgang (looptijd) en de grenswaardecontroles.",
"Im Spiegelbild läuft das Werkzeug andersherum: aus Gleichlauf wird dort Gegenlauf. Die Radiuskorrektur der Steuerung wechselt die Seite mit.":"In het spiegelbeeld loopt het gereedschap andersom: meelopend wordt daar tegenlopend. De radiuscorrectie van de besturing wisselt mee van kant.",
