"Importierte Körper sind ohne Konstruktionshistorie, lassen sich aber weiterbearbeiten (Verrundung, Fase, Ausschneiden …) und für CAM verwenden. Mit „Y-Achse oben“ werden Modelle aus Programmen mit Y nach oben richtig hingestellt.":"Geïmporteerde lichamen hebben geen ontwerpgeschiedenis, maar kunnen verder worden bewerkt (afronding, afschuining, uitsnijden …) en voor CAM worden gebruikt. Met “Y-as boven” worden modellen uit programma’s met Y omhoog goed neergezet.",
