"In „{0}“ wurden keine Bohrungen gefunden (gesucht: runde Durchgangs- und Sacklöcher, auch mit Senkung). Bei Netzen vorher „Netz → Körper“ – dort werden Bohrungen zu echten Zylindern.":"In „{0}” zijn geen gaten gevonden (gezocht: ronde doorlopende en blinde gaten, ook met verzinking). Bij meshes eerst „Mesh → lichaam” – daar worden gaten echte cilinders.",
