"J (relativ)":"J (relatief)",
"JSON kopieren":"JSON kopiëren",
"Je Operation zwei Q-Parameter am Programmanfang: der erste verschiebt die Tiefe (DL, + = weniger tief), der zweite das seitliche Aufmaß (DR, + = mehr Aufmaß; wirkt nur bei Radiuskorrektur an der Steuerung RL/RR). An der Maschine eine Zahl ändern statt Sätze suchen.":"Per bewerking twee Q-parameters aan het begin van het programma: de eerste verschuift de diepte (DL, + = minder diep), de tweede de zijdelingse overmaat (DR, + = meer overmaat; werkt alleen bij radiuscorrectie in de besturing RL/RR). Op de machine één getal wijzigen in plaats van regels zoeken.",
"Je Skizze die erste Kurve – offen oder geschlossen. Die Kurven werden mit einer Haut verbunden (Fläche ohne Dicke).":"Per schets de eerste kromme – open of gesloten. De krommen worden verbonden met een huid (oppervlak zonder dikte).",
"Je Tafel eine Datei. Die Bahn läuft um die halbe Schnittfuge (beim Fräsen den halben Fräser) neben dem Umriss im Abfall; Ausschnitte kommen vor dem Umriss ihres Teils, jede Kontur beginnt mit einem Anschnitt aus dem Abfall. Kiemenschlitze werden auf ihrer Linie geschnitten. Haltestege: so viele Stellen je Umriss bleiben stehen (Laser, Plasma, Wasserstrahl: der Strahl setzt dort aus; Fräsen: der Fräser hebt auf halbe Blechdicke), Umrisse unter 40 mm Länge bekommen keine. „Steuerung“ legt fest, womit der Strahl ein- und ausgeschaltet wird; die Einstechzeit steht als G4 im Programm, außer die Steuerung sticht selbst ein. Nullpunkt ist die linke untere Ecke der Tafel, beim Fräsen Z0 die Blechoberseite. Das Programm vor dem Einsatz an der Maschine oder in einem NC-Simulator prüfen.":"Eén bestand per plaat. De baan loopt een halve snijbreedte (bij frezen de halve frees) naast de omtrek in het afval; uitsneden komen vóór de omtrek van hun deel, elke contour begint met een inloop vanuit het afval. Kieuwsleuven worden op hun lijn gesneden. Houdbruggen: zoveel plaatsen per omtrek blijven staan (laser, plasma, waterstraal: de straal onderbreekt daar; frezen: de frees tilt tot de halve plaatdikte); omtrekken korter dan 40 mm krijgen er geen. “Besturing” bepaalt hoe de straal wordt in- en uitgeschakeld; de doorboortijd staat als G4 in het programma, tenzij de besturing zelf doorboort. Het nulpunt is de linkeronderhoek van de plaat, bij frezen is Z0 de bovenkant van de plaat. Controleer het programma vóór gebruik aan de machine of in een NC-simulator.",
"Je Werkzeug alle Teile (weniger Werkzeugwechsel)":"Per gereedschap alle werkstukken (minder gereedschapswissels)",
"Jede Achse einzeln: Kante, Ecke, Fläche oder Bohrung anklicken. Nicht gesetzte Achsen kommen vom Rohteilpunkt.":"Elke as afzonderlijk: klik op een rand, hoek, vlak of gat. Niet ingestelde assen komen van het ruwmateriaalpunt.",
"Jede Bohrung wird mit ihren Koordinaten einzeln angefahren (X/Y je Bohrung) – kein Lochkreis- oder Rastermuster.":"Elk gat wordt afzonderlijk met zijn coördinaten aangelopen (X/Y per gat) – geen steekcirkel- of rasterpatroon.",
"Jede Operation als Unterprogramm (LBL) am Programmende, Aufruf mit CALL LBL":"Elke bewerking als subprogramma (LBL) aan het einde van het programma, aanroep met CALL LBL",
"Jede Variante berechnen und als STEP, STL oder 3MF speichern (eine ZIP-Datei)":"Elke variant berekenen en als STEP, STL of 3MF opslaan (één ZIP-bestand)",
"Jeder Kreis der Skizze ist ein Bohrungsmittelpunkt. Gebohrt wird entgegen der Skizzennormalen (ins Material).":"Elke cirkel van de schets is het middelpunt van een gat. Er wordt geboord tegen de normaal van de schets in (het materiaal in).",
"Jeder Kreis der Skizze wird um die Mitte (in Skizzenkoordinaten) gedreht wiederholt – ein Kreis im Abstand des Teilkreisradius ergibt einen Lochkreis.":"Elke cirkel van de schets wordt om het middelpunt (in schetscoördinaten) gedraaid herhaald – een cirkel op de afstand van de steekcirkelstraal levert een gatencirkel op.",
"Jeder Kreis der Skizze wird zum Raster: Abstände in X und Y der Skizze (auch negativ).":"Elke cirkel van de schets wordt een raster: afstanden in X en Y van de schets (ook negatief).",
"Jeder Schritt ist gegen Volumen, Körperzahl und Schwerpunkt aus Fusion geprüft. Skizzen kommen mit festen Maßen, ohne Abhängigkeiten.":"Elke stap is gecontroleerd op volume, aantal lichamen en zwaartepunt uit Fusion. Schetsen komen met vaste maten, zonder relaties.",
"Jeder sichtbare Körper wird ein Glied mit Netz (STL, in Metern), Masse und Trägheit, jedes Gelenk ein Gelenk mit Achse und Grenzen. Die jetzige Stellung ist die Nullstellung. Mit einem Paketnamen stehen die Netze im URDF als package://Name/meshes/…, sonst als relativer Pfad.":"Elk zichtbaar lichaam wordt een schakel (link) met mesh (STL, in meters), massa en traagheid, elk scharnier een scharnier (joint) met as en grenzen. De huidige stand is de nulstand. Met een pakketnaam staan de meshes in de URDF als package://Name/meshes/…, anders als relatief pad.",
"Jedes # im Skizzentext wird durch die Nummer ersetzt, mit Nullen aufgefüllt (SN-#### → SN-{0}). Bei mehreren Teilen in einer Aufspannung bekommt jedes Teil die nächste Nummer: {1}{2}.":"Elk # in de schetstekst wordt vervangen door het nummer, aangevuld met nullen (SN-#### → SN-{0}). Bij meerdere werkstukken in één opspanning krijgt elk werkstuk het volgende nummer: {1}{2}.",
"Jedes Design liegt als .ofab-Datei im Ordner und wird nach jeder Änderung neu geschrieben. Dateien, die dort hineinkopiert werden, erscheinen hier.":"Elk ontwerp staat als .ofab-bestand in de map en wordt na elke wijziging opnieuw geschreven. Bestanden die daarin worden gekopieerd, verschijnen hier.",
"Jedes Teil hat seinen eigenen Nullpunkt in der Steuerung (G54, G55 … bzw. Bezugspunkt-Nummer in der Tabelle – Heidenhain Zyklus 247). Alle Nullpunkte vorher an der Maschine setzen.":"Elk werkstuk heeft zijn eigen nulpunt in de besturing (G54, G55 … of referentiepuntnummer in de tabel – Heidenhain cyclus 247). Stel alle nulpunten vooraf op de machine in.",
"Jedes eigene Maß und jeder Toleranzrahmen bekommt eine Nummer in einem Kreis. Die Liste enthält Nennmaß, Toleranz, Höchst- und Mindestmaß und Felder für den Istwert. Maße ohne eigene Toleranz bekommen die Allgemeintoleranz.":"Elke eigen maat en elk tolerantiekader krijgt een nummer in een cirkel. De lijst bevat nominale maat, tolerantie, grootste en kleinste maat en velden voor de werkelijke waarde. Maten zonder eigen tolerantie krijgen de algemene tolerantie.",
"Jetzigen Stand festhalten":"Huidige stand vastleggen",
"Jetzt einen Punkt auf dem zweiten Schenkel.":"Nu een punt op het tweede been.",
