"Kalibrieren: zwei Punkte im Bild anklicken, deren Abstand bekannt ist, und den wirklichen Abstand eingeben – das Bild bekommt den richtigen Maßstab.":"Kalibreren: klik twee punten in de afbeelding aan waarvan de afstand bekend is en voer de werkelijke afstand in – de afbeelding krijgt de juiste schaal.",
