"Kante projiziert":"Rand geprojecteerd",
"Kante {0} (Bogen R{1}, {2} mm)":"Rand {0} (boog R{1}, {2} mm)",
"Kante {0} (Kreis R{1}, {2} mm)":"Rand {0} (cirkel R{1}, {2} mm)",
"Kante {0} ({1} mm)":"Rand {0} ({1} mm)",
"Kante {0} ist zu kurz für eine Lasche":"Rand {0} is te kort voor een flens",
"Kante {0}: Biegewinkel über 180° ist nicht herstellbar.":"Rand {0}: een buighoek boven 180° is niet te maken.",
"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestaucht (Faltengefahr); der Zuschnitt ist dort eine Näherung.":"Rand {0}: flens op een gebogen rand – de rand wordt bij het vormen {1} % samengedrukt (kans op plooien); de uitslag is daar een benadering.",
"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestreckt (Rissgefahr); der Zuschnitt ist dort eine Näherung.":"Rand {0}: flens op een gebogen rand – de rand wordt bij het vormen {1} % uitgerekt (kans op scheuren); de uitslag is daar een benadering.",
"Kante {0}: das Laschenmaß {1} mm ist kleiner als die Biegung ({2} mm)":"Rand {0}: de flensmaat {1} mm is kleiner dan de buiging ({2} mm)",
"Kante {0}: der Bogen ist zu eng für diese Lasche":"Rand {0}: de boog is te krap voor deze flens",
"Kante {0}: die Abstände lassen keine Lasche übrig.":"Rand {0}: de afstanden laten geen flens over.",
"Kante {0}: die Lasche kreuzt eine Biegelinie – mit „Abstand Anfang / Ende“ vor der Biegung enden lassen":"Rand {0}: de flens kruist een buiglijn – laat hem vóór de buiging eindigen met “Afstand begin / einde”",
"Kante {0}: die Lasche liegt in einer Biegezone":"Rand {0}: de flens ligt in een buigzone",
"Kante {0}: ein Ausschnitt gehört zu einer Lasche, die es nicht gibt.":"Rand {0}: een uitsparing hoort bij een flens die niet bestaat.",
"Kante {0}: ein Ausschnitt in der Lasche liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"Rand {0}: een uitsparing in de flens ligt {1} mm naast de buiging (minder dan 2 × plaatdikte) – ze vervormt tijdens het buigen.",
"Kante {0}: ein Ausschnitt liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"Rand {0}: een uitsparing ligt {1} mm naast de buiging (minder dan 2 × plaatdikte) – ze vervormt bij het buigen.",
"Kante {0}: ein Ausschnitt ragt über die Lasche hinaus.":"Rand {0}: een uitsparing steekt buiten de flens uit.",
"Kante {0}{1}: Lasche {2} mm ist kürzer als 2 × Blechdicke – auf der Abkantpresse kaum zu biegen.":"Rand {0}{1}: flens {2} mm is korter dan 2 × plaatdikte – op de kantbank nauwelijks te buigen.",
"Kante {0}{1}: Saum {2} mm ist kürzer als 4 × Blechdicke – er lässt sich schlecht zudrücken.":"Rand {0}{1}: zoom {2} mm is korter dan 4 × plaatdikte – hij is moeilijk dicht te drukken.",
