"Kugel-, Schaft-, Torus- oder Konusfräser. Ein Kugelfräser behält seine Bahn; andere Fräser werden geneigt und entlang ihrer Achse verschoben, bis sie am Teil anliegen, ohne es zu verletzen. Höchstens die größte Neigung; wo Schaft oder Halter das Teil berühren würden, richtet sich das Werkzeug auf. Ausgabe als Werkzeugvektor (Heidenhain, Sinumerik, Fanuc), sonst als 3-Achs-Bahn.":"Kogel-, vinger-, torus- of conische frees. Een kogelfrees behoudt zijn baan; andere frezen worden gekanteld en langs hun as verschoven tot ze tegen het onderdeel liggen zonder het te beschadigen. Maximaal de grootste kanteling; waar de schacht of de houder het onderdeel zou raken, richt het gereedschap zich weer op. Uitvoer als gereedschapsvector (Heidenhain, Sinumerik, Fanuc), anders als 3-assige baan.",
