"Lasche an Lasche: Winkel + biegt in dieselbe Richtung weiter (U-Profil, Falz mit 180°), − in die Gegenrichtung (Z-Stufe, Hutprofil). Saum: der Rand der Lasche wird um 180° auf sich selbst zurückgelegt – offen mit einem Spalt von einer Blechdicke, geschlossen flach zugedrückt; mit − 180° liegt er auf der anderen Seite. Das Feld R ist der Innenradius nur dieser Biegung (leer = wie beim Blech). Für einen Saum direkt an der Plattenkante die Lasche selbst auf 180° stellen. Kröpfung: zwei Biegungen gegeneinander (− 45° und + 45°) – der Rand läuft parallel versetzt weiter; Versatz über die Länge des schrägen Stücks und die Winkel.":"Flens op flens: een hoek + buigt in dezelfde richting verder (U-profiel, felsnaad met 180°), − in de tegenovergestelde richting (Z-trap, hoedprofiel). Zoom: de rand van de flens wordt 180° op zichzelf teruggevouwen – open met een spleet van één plaatdikte, gesloten plat dichtgedrukt; met − 180° ligt hij aan de andere kant. Het veld R is alleen de binnenradius van deze buiging (leeg = zoals bij de plaat). Voor een zoom direct aan de plaatrand stelt u de flens zelf in op 180°. Kropping: twee buigingen tegen elkaar in (− 45° en + 45°) – de rand loopt parallel verschoven verder; de verschuiving volgt uit de lengte van het schuine stuk en de hoeken.",
"Lasche {0}":"Flens {0}",
"Laschen, die über eine Biegelinie laufen, sind dort geteilt und freigestellt.":"Flenzen die over een buiglijn lopen, worden daar gesplitst en vrijgesneden.",
