"Länge L ist die Messlänge aus dem Werkzeug (Nennwert). Die echten Längen an der Maschine oder am Voreinstellgerät messen und eintragen. Heidenhain: Datei nach TNC:\\system\\tooltab kopieren, dann Werkzeugverwaltung → WERKZEUG IMPORT.":"Lengte L is de meetlengte van het gereedschap (nominale waarde). Meet de werkelijke lengtes op de machine of het voorinstelapparaat en voer ze in. Heidenhain: bestand naar TNC:\\system\\tooltab kopiëren, dan gereedschapsbeheer → TOOL IMPORT.",
