"Macht ein geschlossenes Netz hohl: eine Innenwand im Abstand der Wandstärke kommt dazu – spart Material und Druckzeit. Stellen, die dünner sind als zwei Wandstärken, überschneiden sich danach; für Harzdruck ein Ablaufloch mit „Boolesch“ abziehen.":"Maakt een gesloten net hol: er komt een binnenwand bij op de afstand van de wanddikte – bespaart materiaal en printtijd. Plekken die dunner zijn dan twee wanddiktes overlappen daarna; trek voor harsprinten een afvoergat af met “Booleaans”.",
