"Material im Setup unter „Rohteil → Rohteilmaterial“ wählen. Die Dichte ergibt das Rohteilgewicht, Vc ist ein Richtwert für Hartmetall; die Farbe zeigt die Simulation.":"Kies het materiaal in de opspanning onder „Ruw materiaal → Materiaal ruw materiaal“. De dichtheid geeft het gewicht van het ruwe materiaal, Vc is een richtwaarde voor hardmetaal; de kleur toont de simulatie.",
