"Mehrere Schrupp- oder Schlichtdurchgänge gibt es nur als Bahn":"Meerdere ruw- of nabewerkingsgangen bestaan alleen als gereedschapsbaan",
"Mehrere Teile in einer Aufspannung":"Meerdere werkstukken in één opspanning",
"Mehrere Zustellungen und Leerdurchgang gibt es nur als Bahn":"Meerdere aanzetten en een leeg doorgang bestaan alleen als gereedschapsbaan",
"Mehrere aneinanderhängende Kanten zählen als eine Strecke: Der Radius läuft vom Anfang der Kette bis zu ihrem Ende, Stützpunkte gelten in % der ganzen Kettenlänge. Das rechnet der große Geometriekern.":"Meerdere aaneengesloten randen tellen als één traject: de straal loopt van het begin van de keten tot het einde, steunpunten gelden in % van de totale ketenlengte. Dit wordt berekend door de volledige geometriekernel.",
"Mehrfachaufspannung":"Meerdere werkstukken",
"Mehrfachaufspannung: Nullpunkt von Teil {0} gibt es an dieser Steuerung nicht – nur ein Teil ausgegeben":"Meerdere werkstukken: deze besturing heeft geen nulpunt voor werkstuk {0} – slechts één werkstuk uitgevoerd",
"Mehrfachaufspannung: Nullpunktverschiebung gibt es in diesem Postprozessor nicht – „Eigener Nullpunkt je Teil“ wählen; nur ein Teil ausgegeben":"Meerdere werkstukken: deze postprocessor kent geen nulpuntverschuiving – kies ‘Eigen nulpunt per werkstuk’; slechts één werkstuk uitgevoerd",
"Meine Designs · {0}":"Mijn ontwerpen · {0}",
"Meine Werkzeuge":"Mijn gereedschappen",
"Meldet Bahnen, die tiefer schneiden als das Modell an dieser Stelle (Schaft-, Plan-, Kugel- und Torusfräser, Fasenfräser und Bohrer mit ihrem Kegel; 3-Achs-Bewegungen). Ein Schnitt, der nicht im Modell steht – Gravur, Eckenfreistich, Tasche nur aus einer Skizze – wird ebenfalls gemeldet.":"Meldt banen die dieper snijden dan het model op die plek (vingerfrezen, vlakfrezen, kogelfrezen en torusfrezen, afschuinfrezen en boren met hun kegel; 3-assige bewegingen). Een snede die niet in het model staat – gravure, hoekvrijstelling, kamer alleen uit een schets – wordt ook gemeld.",
"Meldung auf dem Bildschirm der Steuerung: Fanuc und LinuxCNC als (MSG, …), Sinumerik als MSG(\"…\"), sonst als Kommentar.":"Melding op het scherm van de besturing: Fanuc en LinuxCNC als (MSG, …), Sinumerik als MSG(\"…\"), anders als commentaar.",
