"Nur lesen: der Agent sieht Entwurf, Modell, Bilder und NC-Programme, kann aber nichts ändern":"Alleen lezen: de agent ziet ontwerp, model, afbeeldingen en NC-programma's, maar kan niets wijzigen",
"Nur mit Korrektur „Im Rechner“.":"Alleen met correctie „In de computer“.",
"Nur stärkste Achse":"Alleen sterkste as",
"Nut":"Gleuf",
"Nut angetrieben":"Gleuf met aangedreven gereedschap",
"Nut angetrieben (C-Achse)":"Gleuf met aangedreven gereedschap (C-as)",
"Nut entlang ihrer Mittellinie fräsen":"Gleuf langs de hartlijn frezen",
"Nut erkannt ({0}) – Heidenhain: CYCL DEF 253 an der Nutmitte, Sinumerik: Taschenzyklus. Die Steuerung fräst mit ihrer eigenen Strategie; die Simulation hier zeigt die Bahn.":"Gleuf herkend ({0}) – Heidenhain: CYCL DEF 253 op het midden van de gleuf, Sinumerik: kamercyclus. De besturing freest met haar eigen strategie; de simulatie hier toont het gereedschapspad.",
"Nut liegt nicht am Teil":"Gleuf ligt niet op het onderdeel",
"Nut längs der Drehachse (z. B. Passfedernut) mit einem angetriebenen Fräser, der zur Achse zeigt; die Hauptspindel hält das Teil als C-Achse. Nutbreite = Fräser-Ø. Start/Ende Z in Modell-Z; reicht die Nut bis zur Planfläche, fährt der Fräser von vorn ein, sonst taucht er am Start ein. Tiefe ab Außendurchmesser.":"Gleuf langs de draaias (bijv. spiebaan) met een aangedreven frees die naar de as wijst; de hoofdspil houdt het onderdeel als C-as vast. Gleufbreedte = frees-Ø. Start-/eind-Z in model-Z; reikt de gleuf tot het voorvlak, dan komt de frees van voren binnen, anders duikt hij bij de start in. Diepte vanaf de buitendiameter.",
"Nut mit angetriebenem Fräser fräsen":"Gleuf frezen met aangedreven frees",
