"Schraubstock: die Backen greifen quer zur X-Achse des Setups (an Y-min und Y-max des Rohteils); 0 = Größe und Spanntiefe passend wählen. Die Spannmittel werden einfache Körper am Ende der Zeitleiste und hier als Spannmittel eingetragen: Halter- und Kollisionsprüfung, Sicherheitsabstände und Einrichteblatt berücksichtigen sie.":"Machineklem: de bekken klemmen dwars op de X-as van de opspanning (aan Y-min en Y-max van het ruw materiaal); 0 = grootte en spandiepte automatisch kiezen. De spanmiddelen worden eenvoudige lichamen aan het einde van de tijdlijn en hier als spanmiddelen ingevoerd: houder- en botsingscontrole, veiligheidsafstanden en opspanblad houden er rekening mee.",
