"Schruppt simultan 4-achsig von außen nach innen: je Zustellung eine Spirale um die A-Achse (abwechselnd in +X und −X), nie tiefer als das Teil plus Aufmaß. Mit Schaft- oder Kugelfräser.":"Voorfreest simultaan 4-assig van buiten naar binnen: per stap een spiraal om de A-as (afwisselend in +X en −X), nooit dieper dan het onderdeel plus overmaat. Met vinger- of kogelfrees.",
