"Verrechnet zwei geschlossene Netze wirklich miteinander: innen liegende Flächen verschwinden, die Schnittkanten werden neu vernetzt. Gerechnet wird nur dort, wo sich die beiden Netze begegnen können – ein großes Netz mit einem kleinen Eingriff geht deshalb schnell. Überlappen zwei große Netze ganz, vorher „Reduzieren“.":"Combineert twee gesloten meshes echt met elkaar: binnenliggende vlakken verdwijnen, de snijranden worden opnieuw gemesht. Er wordt alleen gerekend waar de twee meshes elkaar kunnen ontmoeten – een grote mesh met een kleine ingreep gaat daarom snel. Overlappen twee grote meshes volledig, gebruik dan eerst „Reduceren“.",
