"Verschiebt jede Fläche um den Abstand nach außen (negativ: nach innen) – für Spiel, Aufmaß oder ein Negativ. Kanten und Ecken bleiben scharf; sehr feine Stellen können sich beim Schrumpfen überschneiden.":"Verschuift elk vlak over de afstand naar buiten (negatief: naar binnen) – voor speling, overmaat of een negatief. Randen en hoeken blijven scherp; zeer fijne details kunnen bij krimpen overlappen.",
