"Verschleiß":"Slijtage",
"Verschraubung: Scheiben und Mutter kommen mit der Schraube in einem Zug an jede angeklickte Bohrung. Die Klemmdicke ist die Länge der Bohrung – durch mehrere Teile hindurch, wenn ihre Bohrungen fluchten und aneinanderstoßen. Mit Mutter wird die kürzeste Vorzugslänge vorgeschlagen, bei der die Schraube zwei Gewindegänge aus der Mutter ragt.":"Schroefverbinding: sluitringen en moer worden samen met de schroef in één keer op elk aangeklikt gat geplaatst. De klemdikte is de lengte van het gat – door meerdere delen heen als hun gaten op één lijn liggen en aansluiten. Met moer wordt de kortste voorkeurslengte voorgesteld waarbij de schroef twee schroefdraadgangen uit de moer steekt.",
