"Wie die Ansicht (alle Dreiecke)":"Zoals de weergave (alle driehoeken)",
"Wie fein Körper für STL, 3MF und den Slicer in Dreiecke zerlegt werden: Abweichung von der wahren Fläche als Anteil der Körpergröße. Netze bleiben, wie sie sind.":"Hoe fijn lichamen voor STL, 3MF en de Slicer in driehoeken worden verdeeld: afwijking van het werkelijke oppervlak als deel van de lichaamsgrootte. Netten blijven zoals ze zijn.",
"Wie fein Zylinder, Kugeln und Rundungen in der Ansicht aus Dreiecken bestehen. Feiner sieht runder aus, rechnet bei großen Modellen aber länger. Der Export hat eine eigene Einstellung (3D-Druck).":"Hoe fijn cilinders, bollen en afrondingen in de weergave uit driehoeken bestaan. Fijner ziet er ronder uit, maar rekent bij grote modellen langer. De export heeft een eigen instelling (3D-printen).",
"Wie im System":"Zoals in het systeem",
"Wie lange die Schneide schneiden darf, bevor sie getauscht wird. Das Fenster „Bearbeitungszeit“ rechnet daraus, wie viele Teile noch möglich sind.":"Hoe lang de snijkant mag snijden voordat hij wordt vervangen. Het venster “Bewerkingstijd” berekent hieruit hoeveel stuks nog mogelijk zijn.",
