"Zahnform nach Tredgold (Ersatz-Stirnrad auf dem Rückenkegel), gerade Zähne. Das große Ende liegt in der Grundebene, die Zähne laufen zur Kegelspitze. Für Darstellung, 3D-Druck und Fräsen aus dem Vollen; geschliffene Kegelräder brauchen die Daten des Herstellers.":"Tandvorm volgens Tredgold (vervangend cilindrisch tandwiel op de rugkegel), rechte tanden. Het grote uiteinde ligt in het grondvlak, de tanden lopen naar de kegeltop. Voor weergave, 3D-printen en frezen uit het volle; geslepen kegeltandwielen hebben de gegevens van de fabrikant nodig.",
"Zahnrad: Stirnrad gerade / schräg / Pfeil, Hohlrad, Zahnstange, Kegelrad, Schnecke, Schneckenrad, Kettenrad":"Tandwiel: cilindrisch recht / schuin / pijl, inwendig tandwiel, tandheugel, kegeltandwiel, worm, wormwiel, kettingwiel",
