"Zum Vereinen braucht es zwei Netzkörper.":"Voor samenvoegen zijn twee meshlichamen nodig.",
"Zungen stehen am freien Ende der Lasche über und kommen in den Zuschnitt. „Schlitze als Skizze“ legt die passenden Schlitze dort an, wo die Zungen stehen – je Ebene eine Skizze, jeder Schlitz ringsum um das Spiel größer als die Zunge. In dieser Skizze den Umriss des Gegenstücks zeichnen und daraus ein Blech oder eine Extrusion machen: die Schlitze werden Ausschnitte. Das Gegenstück liegt auf den Laschenenden auf; die Zungenlänge ist üblich gleich seiner Dicke.":"Tongen steken uit aan het vrije einde van de flens en komen in het zaagstuk. „Sleuven als schets” maakt de passende sleuven aan waar de tongen staan – per vlak één schets, elke sleuf rondom met de speling groter dan de tong. Teken in deze schets de contour van het tegenstuk en maak daarvan plaatwerk of een extrusie: de sleuven worden uitsnijdingen. Het tegenstuk rust op de uiteinden van de flenzen; de tonglengte is gewoonlijk gelijk aan zijn dikte.",
