"Zwischen zwei Schnitten hebt das Werkzeug nur so weit ab, wie das Material auf dem Weg es verlangt (Rohteil abzüglich allem, was dieses Setup bis dahin gefräst hat) plus Sicherheitsabstand – und beginnt den Vorschub erst dort.{0}{1}":"Tussen twee sneden tilt het gereedschap alleen zo ver op als het materiaal onderweg vereist (ruw materiaal min alles wat deze opspanning tot dan toe heeft gefreesd) plus veiligheidsafstand – en begint de voeding pas daar.{0}{1}",
