"Übernommen werden Skizzen, Extrusion, Rotation, Bohrung, Verrundung, Fase und Schale als eigene Schritte der Zeitachse. Für alles andere legt das Skript den Stand des Modells als STEP bei, sodass die Form stimmt.":"Schetsen, extrusie, wentelen, gat, afronding, afschuining en schaal worden overgenomen als eigen stappen van de tijdlijn. Voor al het andere voegt het script de stand van het model als STEP toe, zodat de vorm klopt.",
