"„+“ = Werkzeug wird neu angelegt. Schnittdaten sind Richtwerte für Hartmetall ({0}){1}; Kühlung: {2}.":"“+” = gereedschap wordt nieuw aangemaakt. Snijdata zijn richtwaarden voor hardmetaal ({0}){1}; koeling: {2}.",
"„Ineinander schachteln“ legt die Zuschnitte in die Lücken und Buchten ihrer Nachbarn und in deren Ausschnitte (ohne 90°-Drehen nur um 180° gewendet); der Abstand wird nie unterschritten. Ohne den Haken liegen sie nach ihrem umschließenden Rechteck in Reihen. Mit „Skizze + Körper“ entstehen flache Körper in Blechdicke, die sich in der Fertigung mit 2D-Kontur ausschneiden lassen.":"„In elkaar nesten” legt de uitslagen in de open ruimtes en inhammen van hun buren en in hun uitsparingen (zonder 90° draaien alleen 180° omgekeerd); de afstand wordt nooit onderschreden. Zonder het vinkje liggen ze op basis van hun omsluitende rechthoek in rijen. Met „Schets + lichamen“ ontstaan platte lichamen met de plaatdikte, die in de fabricage met een 2D-contour uitgesneden kunnen worden.",
"„Innen/Außen“ braucht geschlossene Konturen – offene Kurven mit „Auf der Kurve“ fräsen":"“Binnen/Buiten” heeft gesloten contouren nodig – open krommen frezen met “Op de kromme”",
"„Prüfen“ fährt den Ablauf in kleinen Zeitschritten ab und meldet, wann welche Körper zusammenstoßen.":"„Controleren” doorloopt de volgorde in kleine tijdstappen en meldt wanneer welke lichamen botsen.",
"„Skizze fertig“ → Extrusion, Rotation oder Bohrung.":"„Schets voltooien” → Extrusie, Wentelen of Gat.",
"„Skizze“ → Ebene XY/XZ/YZ wählen oder eine ebene Fläche anklicken.":"„Schets” → kies vlak XY/XZ/YZ of klik op een vlak oppervlak.",
